-- Google Play Billing catalog (hand-maintained; not generated by `game-db import`).
-- Every product_id must also exist in Play Console with the same id:
--   consumable     -> Monetize > Products > In-app products (gem packs)
--   non_consumable -> Monetize > Products > In-app products (topic packs; see 75_topic_packs.sql)
--   subscription   -> Monetize > Products > Subscriptions (quiz_pass; base plans: monthly, yearly)
-- Prices are set in Play Console only (suggested: gem packs ₹10–499, Quiz Pass
-- ₹49–99/month and ₹499–799/year). To retire a product set active = false;
-- never delete a row that purchases reference.
INSERT INTO billing_products (product_id, kind, title, coins, gems, active, sort_order) VALUES
    ('gems_20',    'consumable',   '20 Gems',    0,   20, true, 1),
    ('gems_110',   'consumable',   '110 Gems',   0,  110, true, 2),
    ('gems_240',   'consumable',   '240 Gems',   0,  240, true, 3),
    ('gems_650',   'consumable',   '650 Gems',   0,  650, true, 4),
    ('gems_1400',  'consumable',   '1,400 Gems', 0, 1400, true, 5),
    ('quiz_pass',  'subscription', 'Quiz Pass',  0,    0, true, 10),
    -- Retired: coins stay free to earn; gems are what is sold.
    ('coins_500',  'consumable',   '500 Coins',   500, 0, false, 90),
    ('coins_1200', 'consumable',   '1,200 Coins', 1200, 0, false, 91),
    ('coins_3000', 'consumable',   '3,000 Coins', 3000, 0, false, 92),
    ('gems_50',    'consumable',   '50 Gems',     0, 50, false, 93),
    ('gems_150',   'consumable',   '150 Gems',    0, 150, false, 94)
ON CONFLICT (product_id) DO UPDATE SET
    kind = EXCLUDED.kind, title = EXCLUDED.title, coins = EXCLUDED.coins, gems = EXCLUDED.gems,
    active = EXCLUDED.active, sort_order = EXCLUDED.sort_order;

-- 'premium' was the first name of the Quiz Pass. Remove it while nothing refers to it.
DELETE FROM billing_products p
 WHERE p.product_id = 'premium'
   AND NOT EXISTS (SELECT 1 FROM client_subscriptions s WHERE s.product_id = p.product_id)
   AND NOT EXISTS (SELECT 1 FROM play_purchases pp WHERE pp.product_id = p.product_id);
UPDATE billing_products SET active = false WHERE product_id = 'premium';
